import numpy as np
# find connected components of background (6) and identify enclosed holes for each frame
def comp(mask):
    h,w=mask.shape; lab=-np.ones((h,w),int); n=0
    for i in range(h):
        for j in range(w):
            if mask[i,j] and lab[i,j]<0:
                stack=[(i,j)]; n+=1
                while stack:
                    a,b=stack.pop()
                    if lab[a,b]>=0: continue
                    lab[a,b]=n
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and mask[x,y] and lab[x,y]<0: stack.append((x,y))
    return lab,n
