                            comp.add((x,y)); st.append((x,y))
                out[r][c]=2 if len(comp)%2==0 else 7
    return out
for key in ['Demo pair 1','Demo pair 2']:
    pred=solve(G[key+' input']); exp=G[key+' output']
    diffs=[p for p in zip(pred,exp) if p[0]!=p[1]]
    print(key,'diffs:',len(diffs), [(i,j,int(a[0]),int(b[0])) for i,(a,b) in enumerate(diffs)])
